import { ACTORS, ATTRIBUTES, EXAMPLE } from './protocol-data.js';
import { VARIANT_ATTRIBUTES, getJourneySteps } from './architecture-variants.js';
import { FIDO_ATTRIBUTES, getStepAttributeOperations } from './attribute-usage.js';
import { applyFidoTransport } from './fido-direct.js';

// This example animates CIBA Poll delivery with login_hint, rather than all modes.
// The trusted authentication service is shown using the existing realmB actor.
// It is an external AuthenticationChannelProvider integration, not an IdP hop.
const cibaCoreUrl='https://openid.net/specs/openid-client-initiated-backchannel-authentication-core-1_0.html';
const cibaKeycloakUrl='https://www.keycloak.org/docs/latest/server_admin/index.html';
const cibaOidcUrl='https://openid.net/specs/openid-connect-core-1_0.html';
const cibaAuthenticationOrigin='https://authenticate.example.test';
const cibaAuthenticationRpId='authenticate.example.test';
const cibaClientId='ciba-client';
const cibaRequestId='ciba_req_7e81';
const cibaBindingMessage='K7M42';
const cibaEndpoint=EXAMPLE.issuerA+'/protocol/openid-connect/ext/ciba/auth';
const cibaCallback=EXAMPLE.issuerA+'/protocol/openid-connect/ext/ciba/auth/callback';
const cibaChannelUri='https://authenticate.example.test/ciba/delegate';
const cibaDefinition=(name,meaning,origin,purpose,example,standard='OpenID CIBA Core 1.0',source=cibaCoreUrl)=>({name,meaning,description:meaning,origin,generator:origin,purpose,example,standard,source});

export const CIBA_ATTRIBUTES={
  cibaBackchannelEndpoint:cibaDefinition('backchannel_authentication_endpoint','The provider metadata address for the direct CIBA authentication request.','Published by Realm A in its OpenID provider metadata.','The confidential client posts here to begin a decoupled authentication transaction.',cibaEndpoint,'OpenID CIBA §4 / §7'),
  cibaDeliveryMode:cibaDefinition('backchannel_token_delivery_mode','The registered delivery mode for the CIBA authentication result.','Registered for the confidential client and constrained by Realm A policy.','This Keycloak example uses poll: the client retrieves tokens from the token endpoint. Polling does not make the authentication device a client callback.','poll','OpenID CIBA §5 / Keycloak CIBA policy',cibaKeycloakUrl),
  cibaLoginHint:cibaDefinition('login_hint','An identifier for the person whose separate device should be contacted.','Obtained by the client from an identified account, such as a username.','Realm A resolves the intended account and trusted authentication service. This hint identifies the person; it is neither user authentication nor confidential-client authentication.','alice','OpenID CIBA §7.1'),
  cibaBindingMessage:cibaDefinition('binding_message','A short visible cue connecting the initiating application and authentication device.','Generated by the client and retained with its pending transaction.','The person compares the cue on both devices before approving the request. It is not a password, authorization code or signed authentication proof.',cibaBindingMessage,'OpenID CIBA §7.1'),
  cibaAuthReqId:cibaDefinition('auth_req_id','The unique handle for this CIBA authentication transaction.','Generated by Realm A after accepting the authenticated backchannel request.','The same authenticated client polls using this handle. Realm A checks client ownership, expiry and approval; the handle alone cannot authenticate the person.',cibaRequestId,'OpenID CIBA §7.3 / §10.1'),
  cibaExpiresIn:cibaDefinition('expires_in (auth_req_id)','The lifetime of the pending CIBA request, in seconds.','Selected by Realm A CIBA policy and returned with auth_req_id.','The client stops polling once the handle expires; this is separate from an access token’s expires_in.','120','OpenID CIBA §7.3'),
  cibaInterval:cibaDefinition('interval','The minimum number of seconds between CIBA token polling requests.','Returned by Realm A and retained by the client.','The client waits between request start times and avoids overlapping requests. A slow_down error adds at least five seconds for all later attempts.','5','OpenID CIBA §7.3 / §10.1 / §11'),
  cibaError:cibaDefinition('error (CIBA polling)','A token endpoint error describing the pending or failed CIBA transaction.','Returned by Realm A while processing an authenticated token poll.','authorization_pending means wait; slow_down also increases the interval by at least five seconds. Stop on expired_token, access_denied, invalid_grant or invalid_request according to the standard.','authorization_pending','OpenID CIBA §11'),
  cibaChannelUri:cibaDefinition('http-authentication-channel-uri','The administrator-configured address of the trusted external authentication service.','Configured in the Keycloak HTTP Authentication Channel Provider.','Realm A delegates device authentication to this controlled service. CIBA does not specify the device transport or factor ceremony.',cibaChannelUri,'Keycloak Authentication Channel Provider',cibaKeycloakUrl),
  cibaCallbackEndpoint:cibaDefinition('Authentication Result Notification endpoint','Keycloak’s endpoint for the trusted authentication service’s result callback.','Defined by the Keycloak HTTP authentication-channel integration.','The controlled service reports its authenticated authorization result here. This backend callback is separate from CIBA client Poll/Ping/Push delivery.',cibaCallback,'Keycloak Authentication Channel Provider',cibaKeycloakUrl),
  cibaChannelAuthorization:cibaDefinition('Authorization (authentication channel)','The callback bearer credential issued to the controlled authentication service.','Created by Realm A and sent only to that service in its delegation request.','The service uses the same bearer credential to authenticate its result notification to A. It remains in their backends; it is not a client_notification_token or a credential for the application/browser.','Bearer <protected per-request callback token>','Keycloak HTTP Authentication Channel Provider',cibaKeycloakUrl),
  cibaConsentRequired:cibaDefinition('is_consent_required','The Keycloak delegation flag indicating whether scope consent is required.','Determined by Realm A client/consent policy.','The controlled service obtains the necessary user authorization decision. This example additionally asks for explicit approval after factor verification.','true','Keycloak HTTP Authentication Channel Provider',cibaKeycloakUrl),
  cibaStatus:cibaDefinition('status (authentication result)','The controlled service’s outcome in the Keycloak result-notification body.','Set by the trusted service after authentication and the required authorization decision.','Keycloak accepts SUCCEED, UNAUTHORIZED or CANCELLED. Only a valid SUCCEED result permits approval; cancelled, unauthorized, expired or unmatched requests must not issue tokens.','SUCCEED','Keycloak HTTP Authentication Channel Provider',cibaKeycloakUrl),
  cibaApproval:cibaDefinition('Authorization decision (local operation)','The person’s explicit decision to permit this identified CIBA request.','Made on the authentication device after comparing binding_message and verifying the required factor.','The trusted authentication service associates the decision with its pending delegation. The browser action’s encoding is implementation-specific, rather than a CIBA request parameter.','Approve the matching K7M42 request','OpenID CIBA §8 / implementation-specific device UI'),
  cibaAuthTime:cibaDefinition('auth_time','The ID-token NumericDate recording when the person was authenticated.','Realm A includes the trusted authentication result’s time under the integration policy.','Lets the receiving client assess authentication freshness when its validation policy requires it. It is a nested ID-token claim; this Poll model has no nonce or auth_req_id ID-token claim.','1791381600 (illustrative)','OIDC Core §2',cibaOidcUrl),
};
export const CIBA_TOPIC_IDS=Object.freeze(Object.keys(CIBA_ATTRIBUTES));
export const CIBA_SOURCES=[
  {name:'OpenID Client-Initiated Backchannel Authentication',standard:'CIBA Core 1.0',url:cibaCoreUrl,note:'Backchannel request, Poll delivery, auth_req_id, approval and polling errors.'},
  {name:'Keycloak CIBA policy and authentication channel',standard:'Current Keycloak product support',url:cibaKeycloakUrl,note:'This example uses Poll/login_hint; an administrator-controlled external authentication service and protected result callback are required.'},
  {name:'Keycloak AuthenticationChannelProvider API',standard:'Keycloak provider integration',url:'https://www.keycloak.org/docs-api/latest/javadocs/org/keycloak/protocol/oidc/grants/ciba/channel/AuthenticationChannelProvider.html',note:'Device authentication is delegated, rather than an application authorization redirect.'},
];

const cibaOp=(ids,kind,actorId,detail,carriedAs)=>ids.map(attributeId=>({attributeId,kind,actorId,detail,...(carriedAs?{carriedAs}:{})}));
const cibaWire=(ids,from,to,detail,carriedAs)=>[...cibaOp(ids,'send',from,detail,carriedAs),...cibaOp(ids,'receive',to,detail,carriedAs)];
const cibaPayload=(name,value,description)=>({name,value,...(description?{description}:{})});
const cibaStage=(key,title,from,to,phase,channel,summary,detail,operations,payload=[],checks=[])=>({id:'ciba-'+key,title,from,to,phase,channel,summary,detail,fields:[...new Set(operations.map(o=>o.attributeId))],payload,checks,attributeOperations:operations,oidcGrant:'ciba',architecture:'web',clientKind:'confidential-ciba',upstream:'single',topology:'single',authenticationEntity:phase==='passkey'||phase==='password'||phase==='otp'||phase==='mfa',cibaStage:key});
const cibaModes=new Set(['passkey','password','one-time-code','password-totp','passkey-totp']);
const cibaNormalize=input=>({mode:cibaModes.has(input?.mode)?input.mode:'passkey',architecture:'web',upstream:'single',authenticator:input?.authenticator==='yubikey'?'yubikey':'hello'});
const cibaText=value=>typeof value==='string'?value.replaceAll(EXAMPLE.origin,cibaAuthenticationOrigin).replaceAll(EXAMPLE.rpId,cibaAuthenticationRpId).replaceAll('opaque-user-B-bytes','opaque-auth-service-user-bytes').replaceAll('Realm%20B','Authentication%20Service').replaceAll('Keycloak Realm B','Trusted authentication service').replaceAll('Realm B','the authentication service').replaceAll('B’s','the authentication service’s').replaceAll("B's",'the authentication service’s').replace(/\bB\b/g,'the authentication service'):value;
const cibaCanonical=step=>String(step.id).match(/(?:^|-)([a-z]\d{2})$/)?.[1];
function cibaFactorSteps(config){
  const selected=getJourneySteps(config.mode,'native','keycloak');
  const factors=applyFidoTransport(selected,config.authenticator).filter(step=>['passkey','password','otp','mfa'].includes(step.phase));
  return factors.map(original=>{
    const canonical=cibaCanonical(original);
    const operations=getStepAttributeOperations(original,config.authenticator).filter(o=>o.kind!=='inspect').map(o=>({...o,attributeId:['p02','p03'].includes(canonical)&&o.attributeId==='userName'?'loginUsername':o.attributeId,detail:cibaText(o.detail)}));
    const copy={...original,id:'ciba-factor-'+original.id,fields:[...new Set(operations.map(o=>o.attributeId))],payload:original.payload.map(p=>({...p,value:cibaText(p.value),...(p.description?{description:cibaText(p.description)}:{})})),checks:original.checks.map(cibaText),attributeOperations:operations,oidcGrant:'ciba',architecture:'web',clientKind:'confidential-ciba',upstream:'single',topology:'single',relyingPartyActor:'realmB',authenticationEntity:true,cibaStage:'factor',attributeValues:{...Object.fromEntries(Object.entries(original.attributeValues||{}).map(([id,value])=>[id,cibaText(value)])),...getCibaExampleOverrides(config)}};
    for(const key of ['title','summary','detail'])copy[key]=cibaText(original[key]);
    if(canonical==='p01')copy.detail='The administrator-controlled authentication service asks for its account password on its own HTTPS authentication-device page. This device authentication is an illustrative configured integration, not a Keycloak CIBA built-in password form, OAuth password grant or application authorization redirect.';
    if(canonical==='p02'||canonical==='p03')copy.detail='The person enters the authentication-service account credentials on '+cibaAuthenticationOrigin+'. The controlled service verifies the protected password credential record and binds the authenticated subject to the delegated login_hint. The initiating application and Realm A do not receive the account password. '+(config.mode==='password-totp'?'Required TOTP verification remains pending.':'Explicit approval of the matching CIBA request remains pending.');
    if(canonical==='l08')copy.detail='The trusted authentication service generates a fresh unpredictable WebAuthn challenge for its pending CIBA-device verification and stores it with the intended account/delegation. Its HTTPS page at '+cibaAuthenticationOrigin+' uses RP ID '+cibaAuthenticationRpId+'. An enrolled credential for this RP is required; no passkey from another RP is automatically accepted. WebAuthn proves identity to this controlled service, which later reports its result to Realm A.';
    if(canonical==='l14')copy.detail='The trusted service verifies the current challenge, exact permitted origin '+cibaAuthenticationOrigin+', RP ID hash, required UP/UV flags and credential signature with its stored public key. It checks that the resulting subject is the account named by the delegated login_hint. '+(config.mode==='passkey-totp'?'Required TOTP is still pending. ':'')+'Even a valid passkey proof does not approve the CIBA request by itself: the explicit authorization decision still follows.';
    if(canonical==='m01')copy.detail='The controlled authentication service requests the already enrolled account’s current TOTP code. Its device verification stays pending until this required check succeeds. This factor policy must be implemented in the configured authentication-channel integration; enabling CIBA in Keycloak does not supply this device flow automatically.';
    if(canonical==='m04')copy.detail='The authentication-device browser posts only the current TOTP code and its device-session context to the controlled authentication service. The TOTP secret stays in the enrolled authenticator app and the service verifier. The initiating application and Realm A do not receive the code or seed.';
    if(canonical==='m05')copy.detail='The trusted service recomputes permitted TOTP candidates from its stored shared secret and agreed settings, validates the configured drift window, attempt protection and one-time-use policy, and associates the successful factor with the account named by login_hint. Explicit approval of the matching CIBA request remains required before the service reports success to Realm A.';
    if(copy.id.endsWith('u03'))copy.detail='The controlled service resolves the identified account and requires that it match the delegated login_hint and already have an enrolled TOTP credential. A username alone never authenticates it; factor verification and explicit approval remain pending.';
    return copy;
  });
}

const cibaStepCache=new Map();
export function getCibaSteps(input={}){
  const config=cibaNormalize(input),key=JSON.stringify(config);if(cibaStepCache.has(key))return cibaStepCache.get(key);
  const requestFields=['authorizationHeaderApp','clientIdApp','clientSecretApp','scope','cibaLoginHint','cibaBindingMessage'];
  const pollFields=['authorizationHeaderApp','clientIdApp','clientSecretApp','grantType','cibaAuthReqId'];
  const tokenFields=['idTokenA','accessTokenA','refreshToken','tokenType','expiresIn'];
  const claims=['issuerA','subjectA','audience','exp','iat','cibaAuthTime'];
  const steps=[
    cibaStage('start','Start a separate-device sign-in','user','app','prepare','local','The person starts a sign-in for an identified account.','This view represents a consumption application backed by a confidential server. The person supplies or selects the account to contact; knowing that account identifier does not authenticate anyone.',cibaWire(['cibaLoginHint'],'user','app','Selects the account identifier for the upcoming decoupled sign-in.','application input'),[cibaPayload('login_hint','alice')]),
    cibaStage('prepare','Prepare a confidential backchannel request','app','app','prepare','internal','The client selects its configured provider and creates a visible matching cue.','The application uses a confidential CIBA-enabled registration, its server-held client secret and poll delivery. It retains a transaction-bound binding_message. There is no application redirect_uri, authorization code, PKCE or OIDC nonce in this illustrated CIBA request.',[...cibaOp(['clientIdApp','clientSecretApp','cibaBackchannelEndpoint','tokenEndpoint','jwksUri','cibaDeliveryMode','scope'],'use','app','Uses registered confidential-client and trusted provider configuration.'),...cibaOp(['authorizationHeaderApp'],'derive','app','Constructs HTTP Basic client authentication from the registered client ID and backend-only secret.'),...cibaOp(['cibaBindingMessage'],'create','app','Creates the short visible cue for this request.'),...cibaOp(['cibaLoginHint','cibaBindingMessage'],'store','app','Associates the intended person and matching cue with this pending consumption-device transaction.')],[cibaPayload('backchannel_authentication_endpoint',cibaEndpoint),cibaPayload('backchannel_token_delivery_mode','poll'),cibaPayload('binding_message',cibaBindingMessage)]),
    cibaStage('request','Ask Realm A through the backchannel','app','realmA','prepare','backchannel','The server requests authentication of the account on its separate device.','The client sends one supported identifying hint, login_hint, plus openid scope and binding_message to the backchannel authentication endpoint. HTTP Basic authenticates the client independently of the person named by login_hint. No browser redirect begins the flow.',cibaWire(requestFields,'app','realmA','Submits the authenticated CIBA backchannel request.','Authorization header and CIBA request form'),[cibaPayload('HTTP','POST '+cibaEndpoint),cibaPayload('Authorization','Basic <encoded ciba-client:backend-secret>'),cibaPayload('scope','openid profile'),cibaPayload('login_hint','alice'),cibaPayload('binding_message',cibaBindingMessage)]),
    cibaStage('accept','Resolve the account and bind the request','realmA','realmA','prepare','internal','Realm A authenticates the registered client and creates a pending request handle.','A checks the enabled CIBA client, allowed scopes and exactly one supported login_hint, then resolves its local account. It creates auth_req_id, a short expiry, minimum polling interval and a separate protected callback credential for the configured external authentication channel. The account is still unauthenticated.',[...cibaOp(['authorizationHeaderApp','clientIdApp','clientSecretApp','scope','cibaLoginHint'],'verify','realmA','Checks confidential-client authentication, CIBA permission and the resolved intended account.'),...cibaOp(['cibaAuthReqId','cibaExpiresIn','cibaInterval','cibaChannelAuthorization'],'create','realmA','Creates a pending client-bound authentication transaction and protected channel callback credential.'),...cibaOp(['cibaChannelUri','cibaCallbackEndpoint','cibaConsentRequired'],'use','realmA','Uses the administrator-controlled device-authentication integration and consent policy.')],[cibaPayload('auth_req_id',cibaRequestId),cibaPayload('Request state','Pending; user not yet authenticated')],['Confidential client authenticated and CIBA enabled','Exactly one supported login_hint resolves the intended account','Request handle bound to this client and expiry']),
    cibaStage('delegate','Delegate authentication to the trusted service','realmA','realmB','broker','backchannel','Realm A asks its controlled authentication service to contact the separate device.','The Keycloak HTTP Authentication Channel Provider calls the administrator-configured external service. Its body identifies the account, requested scopes and visual binding_message; the callback bearer credential stays between the two server backends. This is an integration contract, not an OIDC broker request, device-code grant or client token-delivery callback.',[...cibaOp(['cibaChannelUri'],'use','realmA','Selects the configured administrator-controlled authentication channel.'),...cibaWire(['cibaLoginHint','scope','cibaBindingMessage','cibaConsentRequired','cibaChannelAuthorization'],'realmA','realmB','Delegates authentication and required authorization to the controlled service.','Keycloak authentication-channel HTTPS request')],[cibaPayload('HTTP','POST '+cibaChannelUri),cibaPayload('Authorization','Bearer <protected callback credential>'),cibaPayload('login_hint','alice'),cibaPayload('scope','openid profile'),cibaPayload('binding_message',cibaBindingMessage),cibaPayload('is_consent_required','true')]),
    cibaStage('delegation-ack','Acknowledge the controlled delegation','realmB','realmA','broker','backchannel','The trusted service accepts delivery; it has not yet authenticated the person.','The documented HTTP channel returns 201 to acknowledge the request. The service retains the protected callback credential and request context on its backend; neither becomes browser or user data.',[...cibaOp(['cibaChannelAuthorization','cibaLoginHint','scope','cibaBindingMessage','cibaConsentRequired'],'store','realmB','Retains the delegation context and callback credential on the trusted service backend.')],[cibaPayload('HTTP','201 Created')]),
    cibaStage('register-request','Commit the accepted pending request','realmA','realmA','prepare','internal','Realm A stores the pending transaction after its controlled channel accepts the delegation.','The controlled service has acknowledged receipt, so Keycloak retains the request owner, intended account, cue, lifetime and protected result-callback correlation before returning auth_req_id. Device authentication and authorization still happen asynchronously; channel acceptance is not user authentication.',cibaOp(['cibaAuthReqId','clientIdApp','cibaLoginHint','cibaBindingMessage','cibaExpiresIn','cibaChannelAuthorization'],'store','realmA','Stores the pending client/account transaction only after the configured authentication channel accepts it.'),[cibaPayload('Local request state','Pending; controlled delegation accepted')]),
    cibaStage('handle','Return a request handle, not tokens','realmA','app','prepare','backchannel','The client receives the pending handle, lifetime and polling interval.','This response acknowledges the accepted backchannel request; it does not mean the user has authenticated or approved it. expires_in here is the auth_req_id lifetime, not an access-token lifetime.',cibaWire(['cibaAuthReqId','cibaExpiresIn','cibaInterval'],'realmA','app','Returns the accepted pending request handle and polling controls.','CIBA authentication response JSON'),[cibaPayload('HTTP','200 OK'),cibaPayload('auth_req_id',cibaRequestId),cibaPayload('expires_in','120'),cibaPayload('interval','5')]),
    cibaStage('consumption-cue','Display the matching cue where sign-in began','app','user','prepare','local','The initiating application shows the cue to compare on the separate device.','The consumption application displays its locally retained binding_message and the request context. The person later compares this cue with the authentication-device screen before approving. The cue provides visual transaction recognition; it does not prove authentication.',cibaWire(['cibaBindingMessage','scope'],'app','user','Shows the transaction cue and requested scope on the consumption-device display.','consumption-device UI'),[cibaPayload('binding_message',cibaBindingMessage),cibaPayload('Application UI','Waiting for separate-device approval')]),
    cibaStage('retain','Retain the handle and respect interval','app','app','prepare','internal','The client keeps its pending request and waits before polling.','Polling is a backend timer, separate from the device interaction. Do not overlap requests for one auth_req_id. This simulator advances illustrative time; animation speed never represents a real network polling rate.',[...cibaOp(['cibaAuthReqId','cibaExpiresIn','cibaInterval'],'store','app','Stores the request handle, request lifetime and server minimum interval.'),...cibaOp(['cibaInterval','cibaExpiresIn'],'use','app','Schedules non-overlapping polls and stops at request expiry.')],[cibaPayload('Local timer','Wait at least interval seconds between request start times')]),
    cibaStage('poll-pending','Poll while device approval is pending','app','realmA','tokens','backchannel','The confidential client checks for its authentication result.','The token request contains the CIBA grant type and the client-owned auth_req_id, with the registered confidential-client authentication. The client does not redeem an authorization code or device_code.',[...cibaOp(['grantType'],'use','app','Selects the CIBA token-polling grant.'),...cibaWire(pollFields,'app','realmA','Polls for this client’s pending authentication transaction.','Authorization header and token request form')],[cibaPayload('HTTP','POST '+EXAMPLE.tokenA),cibaPayload('Authorization','Basic <encoded ciba-client:backend-secret>'),cibaPayload('grant_type','urn:openid:params:grant-type:ciba'),cibaPayload('auth_req_id',cibaRequestId)]),
    cibaStage('pending','Return authorization_pending','realmA','app','tokens','backchannel','Realm A reports that authentication and approval have not finished.','A authenticates the polling client and checks the request belongs to it and has not expired. authorization_pending is a wait signal, never a successful login. A request for another client’s handle must fail.',[...cibaOp(['authorizationHeaderApp','clientIdApp','clientSecretApp','cibaAuthReqId','cibaExpiresIn'],'verify','realmA','Checks authenticated client ownership and pending request validity.'),...cibaOp(['cibaError'],'create','realmA','Produces authorization_pending while required device authentication/approval is incomplete.'),...cibaWire(['cibaError'],'realmA','app','Returns the pending token-endpoint error.','OAuth token error response JSON')],[cibaPayload('HTTP','400 Bad Request'),cibaPayload('error','authorization_pending')]),
    cibaStage('backoff','Wait safely or stop on terminal errors','app','app','tokens','internal','The client continues only while the request remains valid.','On authorization_pending, keep the current minimum interval. On slow_down, increase it by at least five seconds for this and every later request. Do not overlap polls; stop on expiry, access_denied, invalid_grant or invalid_request. The successful path shown here receives authorization_pending.',[...cibaOp(['cibaError'],'verify','app','Classifies a pending response versus a terminal error.'),...cibaOp(['cibaInterval','cibaExpiresIn'],'use','app','Waits for the required interval without overlapping requests; slow_down would add at least five seconds.')],[cibaPayload('Local polling policy','pending → wait; slow_down → interval + ≥5 seconds; terminal error → stop')]),
    cibaStage('notify-device','Contact the separate authentication device','realmB','browser','broker','https','The trusted service shows the intended application request and the matching cue.','The configured authentication service contacts its enrolled device using its own controlled mechanism. This teaching device opens a secure page at '+cibaAuthenticationOrigin+'. The initiating application is not redirecting this browser, and the backend callback credential is not sent to the device.',cibaWire(['cibaBindingMessage','scope'],'realmB','browser','Displays request context on the separate authentication device.','configured authentication-device channel'),[cibaPayload('Device page',cibaAuthenticationOrigin+'/approve'),cibaPayload('binding_message',cibaBindingMessage),cibaPayload('scope','openid profile')]),
    ...cibaFactorSteps(config),
    cibaStage('compare','Compare the matching cue on both devices','browser','user','complete','local','The person recognizes the same request cue before approving.','The initiating application displayed '+cibaBindingMessage+' and the authentication device displays the same cue with the requesting client and scopes. Reject unfamiliar requests; factor verification alone does not authorize this transaction.',cibaWire(['cibaBindingMessage','scope'],'browser','user','Shows the binding cue and requested scope for explicit user inspection.','authentication-device display'),[cibaPayload('binding_message',cibaBindingMessage),cibaPayload('Visible action','Approve this matching request, or deny')]),
    cibaStage('approve','Approve this specific verified request','user','browser','complete','local','The person explicitly approves the intended authentication request.','This is the required authorization decision after the selected factor checks. It must be bound to the controlled service’s current delegation; a generic approval of an unrelated notification cannot complete it.',[...cibaOp(['cibaBindingMessage'],'verify','user','Compares the cue with the intended consumption-device request.'),...cibaOp(['cibaApproval'],'create','user','Makes an explicit authorization decision for this identified request.'),...cibaWire(['cibaApproval'],'user','browser','Chooses the device UI action for the current verified request.','local UI action')],[cibaPayload('Authorization decision (local operation)','Approve matching request')]),
    cibaStage('decision','Submit approval to the controlled service','browser','realmB','complete','https','The authentication device submits the transaction-bound authorization decision.','The device-service approval action is an implementation-specific HTTPS action. The controlled service accepts it only after required factor verification and intended-account checks, while its delegation remains pending. It sends no user password, OTP code, passkey private key or assertion to the consumption application.',cibaWire(['cibaApproval'],'browser','realmB','Returns the explicit decision through the controlled authentication-service action.','implementation-specific device approval action'),[cibaPayload('HTTPS action',cibaAuthenticationOrigin+'/approve'),cibaPayload('Authorization decision (local operation)','Approve current verified delegation')]),
    cibaStage('prepare-result','Bind the authenticated person and decision','realmB','realmB','complete','internal','The trusted service records success for the correct person and request.','The service verifies that the authenticated subject matches its delegated login_hint, that the user compared the intended binding_message and explicitly approved, and that the required factor policy succeeded. It retains the protected callback bearer credential and creates the SUCCEED result only after these checks.',[...cibaOp(['cibaLoginHint','cibaBindingMessage','cibaApproval','cibaConsentRequired'],'verify','realmB','Checks intended subject, transaction-bound explicit approval and required authorization policy.'),...cibaOp(['cibaStatus'],'create','realmB','Creates SUCCEED only after required device factors and authorization have succeeded.')],[cibaPayload('status','SUCCEED')],['Authenticated subject matches delegated login_hint','Required factors verified by controlled service','Explicit authorization decision bound to this request']),
    cibaStage('result','Notify Realm A of the protected result','realmB','realmA','tokens','backchannel','The trusted authentication service reports success directly to Realm A.','The service calls Keycloak’s result-notification endpoint using the same protected bearer credential from the delegation. Its status body reports the outcome. This is not CIBA Push token delivery: no tokens are sent to the client here, and the authentication-device browser does not make this backend callback.',[...cibaOp(['cibaCallbackEndpoint'],'use','realmB','Uses the configured Keycloak result-notification endpoint.'),...cibaWire(['cibaChannelAuthorization','cibaStatus'],'realmB','realmA','Reports the device verification and authorization outcome to the original pending delegation.','Keycloak authentication result callback HTTPS')],[cibaPayload('HTTP','POST '+cibaCallback),cibaPayload('Authorization','Bearer <same protected callback credential>'),cibaPayload('status','SUCCEED')]),
    cibaStage('approved','Accept only the matching trusted result','realmA','realmA','tokens','internal','Realm A verifies the callback and marks its original request approved.','A authenticates the result callback, binds it to its pending client/account/delegation, checks success and the request lifetime, then records the approved authentication result. An expired, unmatched, denied or unauthorized callback must not produce tokens.',[...cibaOp(['cibaChannelAuthorization','cibaStatus','cibaAuthReqId','cibaExpiresIn'],'verify','realmA','Authenticates callback correlation and checks valid successful pending-request state.'),...cibaOp(['cibaAuthReqId','cibaStatus'],'store','realmA','Records approval only for the original client-bound CIBA request.')],[cibaPayload('Local CIBA request state','Approved for ciba-client; awaiting authenticated token poll')]),
    cibaStage('poll-approved','Poll again after device approval','app','realmA','tokens','backchannel','The client retrieves the now-approved result using the same request handle.','The backend waits for the polling interval and repeats its authenticated CIBA token request. Realm A checks that the auth_req_id belongs to this client, is unexpired, is approved and has not already been redeemed. Successful redemption makes this handle invalid for any later token request.',[...cibaOp(['cibaInterval'],'use','app','Respects the current minimum interval before this non-overlapping poll.'),...cibaWire(pollFields,'app','realmA','Retrieves the approved result using the authenticated original client.','Authorization header and token request form')],[cibaPayload('HTTP','POST '+EXAMPLE.tokenA),cibaPayload('Authorization','Basic <encoded ciba-client:backend-secret>'),cibaPayload('grant_type','urn:openid:params:grant-type:ciba'),cibaPayload('auth_req_id',cibaRequestId)]),
    cibaStage('issue','Validate the approved handle and sign tokens','realmA','realmA','tokens','internal','Realm A issues tokens only after the trusted device result and final client checks.','A checks client authentication, auth_req_id ownership, expiry, approved state and redemption policy. It uses its own realm signing key for the ID token and maps the trusted result to its intended local subject. Poll CIBA has no authorization code, PKCE verifier or original nonce in this example. The ID token does not invent an auth_req_id claim from the Push-mode rules.',[...cibaOp(['authorizationHeaderApp','clientIdApp','clientSecretApp','cibaAuthReqId','cibaExpiresIn','cibaStatus'],'verify','realmA','Checks the authorized original client and approved unexpired pending handle.'),...cibaOp(['realmSigningKey','clientIdApp'],'use','realmA','Uses its own issuer signing key and registered receiving-client identifier.'),...cibaOp([...claims,...tokenFields],'create','realmA','Creates the validated local subject’s normal signed OIDC token response.'),...cibaOp(['cibaAuthReqId'],'store','realmA','Records completed redemption under request-handle replay policy.')],[cibaPayload('Local issuer','Realm A'),cibaPayload('Local subject','user-in-A-204'),cibaPayload('ID-token audience',cibaClientId)],['Authenticated polling client owns auth_req_id','Request approved, valid and not previously consumed','Issuer signs with its own private key']),
    cibaStage('l24','Return the CIBA tokens directly to the client','realmA','app','tokens','backchannel','The confidential backend receives the identity and access result over HTTPS.','The successful authenticated Poll response carries an ID token for ciba-client, an access token and any policy-authorized refresh token. Nested claims describe Realm A’s verified local identity. The result stays on the consumption application backend; it is not sent to the separate authentication device.',[...cibaWire(tokenFields,'realmA','app','Returns the successful signed OIDC token response.','HTTPS token response JSON'),...cibaWire(claims,'realmA','app','Claims are nested in the signed id_token, rather than separate HTTP response members.','id_token claims')],[cibaPayload('id_token','Realm A signed JWT for ciba-client'),cibaPayload('access_token','A-issued access token'),cibaPayload('refresh_token','Optional under client/realm policy'),cibaPayload('token_type','Bearer'),cibaPayload('expires_in','300'),cibaPayload('iss',EXAMPLE.issuerA,'Nested ID-token claim.'),cibaPayload('aud',cibaClientId,'Nested ID-token claim.'),cibaPayload('sub','user-in-A-204','Nested ID-token claim.'),cibaPayload('auth_time','1791381600','Nested ID-token claim.')]),
    cibaStage('l25','Validate identity at the consumption backend','app','app','tokens','internal','The client validates the issuer’s identity result for its own pending request.','The confidential client associates this authenticated token response with its retained CIBA polling transaction, validates the ID-token issuer signature using A’s trusted verification keys, exact issuer, registered client audience, lifetime and required claim/assurance policy. There is no authorization-code callback, PKCE or nonce check in this Poll example. Successful device authentication does not let the client skip token validation.',[...cibaOp(['cibaAuthReqId'],'use','app','Associates this authenticated Poll response with its original pending transaction.'),...cibaOp(['jwksUri','clientIdApp'],'use','app','Uses trusted issuer verification keys and its own client registration.'),...cibaOp(['idTokenA',...claims],'verify','app','Validates the ID-token signature, intended issuer/client, valid lifetime and configured identity/freshness policy.'),...cibaOp(['idTokenA','accessTokenA','refreshToken'],'store','app','Keeps validated tokens in the consumption application backend.')],[cibaPayload('Validated identity','Realm A / user-in-A-204'),cibaPayload('Client audience check',cibaClientId)],['Expected issuer signature and exact iss valid','aud includes ciba-client','Lifetime and configured freshness/assurance policy valid','Response matched to original authenticated polling transaction']),
    cibaStage('complete','Show success in the initiating application','app','user','complete','local','The person sees the completed sign-in where the request began.','The consumption application displays its validated result. The separate authentication device has fulfilled its verification/approval role; it does not receive the application’s tokens or become its OAuth callback.',[],[cibaPayload('Application UI','Signed in after separate-device approval')]),
  ];
  for(const step of steps){step.attributeValues={...getCibaExampleOverrides(config),...step.attributeValues};if(step.id==='ciba-l24')step.idTokenClaimIds=[...claims];}
  cibaStepCache.set(key,steps);return steps;
}

export function getCibaExampleOverrides(){return {clientIdApp:cibaClientId,clientSecretApp:'Confidential CIBA backend secret; never sent to either browser',authorizationHeaderApp:'Basic <encoded ciba-client:backend-secret>',grantType:'urn:openid:params:grant-type:ciba',scope:'openid profile',audience:cibaClientId,idTokenA:'JWT: iss=A, aud=ciba-client, sub=user-in-A-204, auth_time=…; no nonce in this Poll example',subjectA:'user-in-A-204',rpId:cibaAuthenticationRpId,origin:cibaAuthenticationOrigin,rpIdHash:'SHA256("'+cibaAuthenticationRpId+'")',challengeLogin:'fresh authentication-service WebAuthn challenge bytes',clientDataJSON:'{type: "webauthn.get", challenge: "…", origin: "'+cibaAuthenticationOrigin+'"}',userId:'opaque-auth-service-user-bytes',userHandle:'opaque-auth-service-user-bytes',ctapUser:'{ id: opaque-auth-service-user-bytes }',otpUri:'Already enrolled; no secret provisioned during CIBA sign-in',...Object.fromEntries(Object.entries(CIBA_ATTRIBUTES).map(([id,def])=>[id,def.example]))};}

export function getCibaAttributeOverrides(input={}){
  const examples=getCibaExampleOverrides(input),definitions={...ATTRIBUTES,...VARIANT_ATTRIBUTES,...FIDO_ATTRIBUTES,...CIBA_ATTRIBUTES},result={};
  // Return complete factor definitions, not only changed example values. The
  // UI's generic single-realm context must not relabel this controlled service
  // as Realm A or imply that Realm A directly verifies these device factors.
  const factorIds=new Set(['session','challengeLogin','rpId','origin','allowCredentials','userVerification','timeout','privateKey','credentialPublicKey','credentialId','credentialType','clientDataJSON','clientDataHash','clientDataType','crossOrigin','authenticatorData','rpIdHash','flagsUP','flagsUV','signCount','signature','userHandle','localVerification','password','passwordHash','loginUsername','otpSecret','otpAlgorithm','otpDigits','otpPeriod','otpT0','otpTime','otpCounter','otpCode','otpWindow','otpReplay','ctapGetAssertion','pinUvAuthParam','pinUvAuthProtocol','pinUvAuthToken',...getCibaSteps(input).filter(stage=>stage.authenticationEntity).flatMap(stage=>stage.fields)]);
  for(const id of factorIds)if(definitions[id])result[id]=Object.fromEntries(Object.entries(definitions[id]).map(([property,value])=>[property,cibaText(value)]));
  for(const [id,example]of Object.entries(examples))if(definitions[id])result[id]={...(result[id]||definitions[id]),example};
  const patch=(id,changes)=>{result[id]={...definitions[id],...result[id],...changes};if(changes.meaning)result[id].description=changes.meaning;if(changes.origin)result[id].generator=changes.origin;};
  patch('clientIdApp',{meaning:'The public identifier of the confidential CIBA client registration in Realm A.',origin:'Registered by an administrator for the server application with CIBA enabled.',purpose:'Identifies the authenticated backend and binds its auth_req_id/token audience to this client. In this HTTP Basic example it is carried in client authentication, rather than an authorization URL.',standard:'RFC 6749 §2.2 / OpenID CIBA §7.1 / §10.1',source:cibaCoreUrl});
  patch('clientSecretApp',{meaning:'The server-held credential authenticating the confidential CIBA client.',origin:'Provisioned for the ciba-client registration and retained on its backend.',purpose:'Authenticates both the direct backchannel request and token polls. It is separate from login_hint, account passwords, auth_req_id and the authentication-channel callback bearer credential.',standard:'RFC 6749 §2.3.1 / OpenID CIBA §7.1',source:cibaCoreUrl});
  patch('authorizationHeaderApp',{meaning:'The HTTP Basic client-authentication header for CIBA backend requests.',origin:'Constructed by the confidential backend using its registered client_id and protected secret.',purpose:'Authenticates the client at the backchannel and token endpoints; it never travels through the authentication-device browser.',standard:'RFC 6749 §2.3.1 / OpenID CIBA §7.1 / §10.1',source:cibaCoreUrl});
  patch('grantType',{meaning:'The token-endpoint operation used to poll for the CIBA authentication result.',origin:'Set by the confidential CIBA client.',purpose:'urn:openid:params:grant-type:ciba asks for the result associated with auth_req_id; no authorization code or device code is used.',standard:'OpenID CIBA §10.1',source:cibaCoreUrl});
  patch('idTokenA',{meaning:'The signed identity token issued by Realm A after CIBA authentication and approval.',origin:'Realm A signs its local user identity with its own realm signing key.',purpose:'The confidential client verifies issuer signature, issuer, audience, lifetime and its configured claim policy. This Poll example contains no OIDC nonce or auth_req_id ID-token claim.',standard:'OpenID CIBA §10.1 / OIDC Core §2',source:cibaCoreUrl});
  patch('tokenEndpoint',{meaning:'Realm A’s direct endpoint for authenticated CIBA result polling.',origin:'Published in Realm A’s trusted provider metadata.',purpose:'The confidential application posts the CIBA grant and auth_req_id here while honoring expiry and minimum polling interval.',standard:'OpenID CIBA §10.1',source:cibaCoreUrl});
  patch('subjectA',{meaning:'The intended local Realm A account authenticated through its controlled CIBA integration.',origin:'Realm A resolves login_hint, then accepts only the matching trusted authentication-service result.',purpose:'Identifies the verified user together with Realm A’s iss; the external authentication service is not an OIDC broker IdP.'});
  for(const id of ['challengeLogin','credentialPublicKey','allowCredentials','passwordHash','otpSecret','otpWindow','otpReplay'])if(definitions[id])patch(id,{origin:'Held, generated or enforced by the configured trusted authentication service for the identified enrolled account.',purpose:id==='challengeLogin'?'Binds the WebAuthn proof to this authentication-service verification; approval of the CIBA request remains separate.':id==='credentialPublicKey'?'The authentication service verifies its RP’s credential signature; Realm A trusts the protected integration result.':id==='allowCredentials'?'An empty list permits discovery of an enrolled credential for the authentication service RP; its subject must still match the delegated login_hint.':id==='passwordHash'?'The controlled service checks its protected account password verifier locally; it never sends the record or password to Realm A.':id==='otpSecret'?'The seed stays in the already enrolled TOTP app and controlled service verifier; CIBA carries neither the seed nor the code to the initiating client.':id==='otpWindow'?'The authentication-service TOTP verifier applies its configured limited clock-drift policy.':'The controlled authentication-service verifier must reject a second successful use of the same OTP time step.'});
  for(const id of ['password','otpCode','loginUsername','session'])if(definitions[id])patch(id,{purpose:id==='password'?'Proves the knowledge factor to the controlled authentication service; neither Realm A nor the CIBA client receives it.':id==='otpCode'?'Proves the possession factor to the controlled authentication service, not to the initiating CIBA client or Realm A.':id==='loginUsername'?'Identifies the enrolled authentication-service account, which must match the account named by delegated login_hint.':'The trusted authentication service keeps its own pending device session and factor context; it is not the application’s OAuth browser session.'});
  patch('rpId',{origin:'Configured by the trusted authentication service for its WebAuthn relying party.',purpose:'Scopes the selected authenticator credential to authenticate.example.test; the credential must already be enrolled for this authentication service.'});
  patch('challengeLogin',{origin:'Fresh unpredictable bytes generated by the trusted authentication service and retained in its pending device-verification context.'});
  patch('allowCredentials',{origin:'Prepared by the trusted authentication service from its enrolled credential/account records, or left empty for discoverable-credential selection.'});
  patch('privateKey',{purpose:'Proves possession of the authentication-service RP credential. The key stays protected in the selected authenticator/provider; it is never sent to either server or the initiating application.'});
  patch('credentialPublicKey',{origin:'Generated by the selected authenticator and supplied during prior verified credential enrollment; the trusted service stores the public key with its account binding.'});
  patch('origin',{origin:'The authentication-device browser derives it from the loaded HTTPS authentication-service page.',purpose:'The trusted authentication service checks the exact allowed origin https://authenticate.example.test when verifying the WebAuthn proof.'});
  patch('rpIdHash',{purpose:'The trusted authentication service compares the signed value with SHA256("authenticate.example.test") to verify its own RP binding.'});
  patch('userHandle',{purpose:'The authentication service resolves its enrolled account, checks the credential belongs to it and matches that verified person to the delegated login_hint. It is not an OIDC sub.'});
  if(result.ctapCredential)patch('ctapCredential',{purpose:'The local browser maps this authentication-service credential descriptor to WebAuthn rawId/id; the trusted service later resolves its enrolled account association.'});
  if(result.ctapAuthData)patch('ctapAuthData',{purpose:'The local browser maps the CTAP bytes to WebAuthn response.authenticatorData. The trusted authentication service checks the signed RP binding for authenticate.example.test; Realm A receives only the protected integration result.'});
  if(result.ctapSignature)patch('ctapSignature',{purpose:'The browser preserves these CTAP signature bytes as WebAuthn response.signature; the controlled authentication service verifies them with its stored credential public key before explicit CIBA approval.'});
  if(result.ctapUser)patch('ctapUser',{origin:'The security key reads the enrolled account association for the trusted authentication-service RP authenticate.example.test.',purpose:'The browser maps the selected user.id to WebAuthn response.userHandle. The controlled service checks that the enrolled account matches delegated login_hint before approval.',example:'{ id: opaque-auth-service-user-bytes }'});
  patch('userVerification',{origin:'Required by the configured authentication-service WebAuthn policy and requested on its device page.',purpose:'The selected local authenticator performs PIN/biometric verification; the controlled service requires the signed UV flag when verifying the proof.'});
  patch('session',{name:'Device authentication session (implementation-specific)',meaning:'The controlled authentication service’s pending device-verification and authorization context.',origin:'Created and retained by the trusted authentication service for its delegated device interaction.',purpose:'Binds its factor submissions and explicit approval to the intended person and pending CIBA delegation. It is separate from Realm A’s auth_req_id and any application session.',example:'Pending authentication-service device session; factor verification + explicit approval required',standard:'Implementation-specific authentication-device session; OpenID CIBA §8',source:cibaCoreUrl});
  patch('password',{meaning:'The account password submitted to the controlled authentication service’s secure device action.',example:'Password submitted to the trusted authentication service over HTTPS; value hidden',standard:'Provider-specific authentication-service form; not an OAuth parameter'});
  patch('passwordHash',{meaning:'The controlled authentication service’s protected account-password verification record, including algorithm and salt metadata.',origin:'Created by the controlled service’s credential provider during prior account-password setup.',standard:'Provider-specific authentication-service credential storage'});
  patch('otpCode',{name:'otp (authentication-service form field)',meaning:'The short numeric TOTP code entered on the controlled authentication service’s device page.',standard:'RFC 6238 algorithm / implementation-specific authentication-service form'});
  patch('otpSecret',{meaning:'The previously enrolled symmetric secret shared by the trusted authentication service’s verifier and the person’s TOTP app.',origin:'Provisioned during earlier verified enrollment with the controlled authentication service; no new secret is issued during this CIBA sign-in.'});
  patch('otpWindow',{example:'Authentication-service policy permits a limited configured clock-drift window; independent of Keycloak CIBA policy.',standard:'RFC 6238 §5.2 / §6 and authentication-service verifier policy'});
  patch('otpReplay',{standard:'RFC 6238 §5.2 and authentication-service verifier policy'});
  patch('loginUsername',{meaning:'An account identifier entered on the controlled authentication service’s device form.',origin:'Provisioned for the enrolled authentication-service account, then entered by the person.',standard:'Provider-specific authentication-service form; not an OAuth/OIDC parameter'});
  return result;
}

const cibaActorCache=new Map();
export function getCibaActorOverrides(input={}){
  const config=cibaNormalize(input),key=JSON.stringify(config);if(cibaActorCache.has(key))return cibaActorCache.get(key);
  const steps=getCibaSteps(config),attributesByActor={};
  const staticIds=new Set(['clientIdApp','clientSecretApp','cibaBackchannelEndpoint','tokenEndpoint','jwksUri','cibaDeliveryMode','scope','cibaChannelUri','cibaCallbackEndpoint','cibaConsentRequired','realmSigningKey','credentialPublicKey','passwordHash','otpSecret','otpAlgorithm','otpDigits','otpPeriod','otpT0','otpWindow','privateKey','rpId','origin','userVerification','otpReplay']);
  for(const step of steps)for(const op of step.attributeOperations){const list=attributesByActor[op.actorId]||=([]);let kind=staticIds.has(op.attributeId)?'static':['create','derive'].includes(op.kind)?'generated':op.kind==='receive'?'received':'static';const old=list.find(a=>a.id===op.attributeId);if(!old)list.push({id:op.attributeId,kind});else if(kind==='generated'&&old.kind!=='static')old.kind=kind;}
  const overrides={
    user:{name:'Person',role:'End user · two-device approval',plainRole:'Compares the matching cue, verifies the required factors and approves the request.',notes:['Uses the consumption application and a separate authentication device.','Account identification and a notification alone never authenticate the person.','Required factors and an explicit authorization decision both precede token issuance.']},
    app:{name:'Consumption application',role:'Confidential OIDC CIBA client',plainRole:'Requests separate-device verification directly and polls for its own result.',notes:['Client authentication enabled and CIBA permission configured in Realm A.','Keeps its client secret, auth_req_id, polling timer and tokens on its backend.','Poll delivery: no application redirect_uri, authorization code, PKCE or ID-token nonce in this example.','The local application input/output is a consumption-device UI abstraction; its transport is outside CIBA.']},
    browser:{name:'Authentication device',role:'Separate device browser / WebAuthn client',plainRole:'Shows the controlled service’s secure verification and approval page.',notes:['Separate from the consumption-device application.','The configured authentication channel initiates the device interaction; no app authorization redirect is used.','WebAuthn RP: authenticate.example.test; the selected credential must be enrolled for this RP.','Never receives the confidential client secret, callback bearer credential or application tokens.']},
    realmA:{name:'Keycloak · Realm A',role:'OIDC CIBA provider',plainRole:'Binds the client’s pending request to trusted device verification and issues its tokens.',notes:['One Keycloak realm; the controlled service on the right is not a second realm or broker IdP.','This example animates poll delivery with login_hint; other modes and identifying-hint variants are not shown.','Requires a configured AuthenticationChannelProvider and an administrator-controlled authentication service.','Authenticates the confidential client, correlates protected callback results and checks request ownership/expiry/approval before tokens.']},
    realmB:{name:'Trusted authentication service',role:'Controlled CIBA authentication-channel integration',plainRole:'Authenticates the intended person on their separate device and returns a protected result.',notes:['Represents the external administrator-controlled entity required by Keycloak’s AuthenticationChannelProvider.','The illustrated password/WebAuthn/TOTP device policy is an example implementation, not a built-in Keycloak CIBA factor flow.','Uses RP authenticate.example.test and checks the verified account matches delegated login_hint.','Keeps the callback bearer credential on its backend, requires explicit approval, then reports status to Realm A.']},
    totp:{notes:['Already enrolled with the controlled authentication service; this sign-in never provisions a new seed.','Computes the time-based code locally; sends neither seed nor code to the CIBA client or Realm A.']},
    yubikey:{notes:['The credential must be enrolled for authenticate.example.test.','The browser/platform uses local CTAP2 PIN/UV authorization and user presence.','The private credential key never leaves its protected environment.']},
    hello:{notes:['The credential must be enrolled for authenticate.example.test.','Windows Hello verifies locally and returns its signed assertion to the device browser.','The private credential key and biometric/PIN material are not sent to the servers.']},
  };
  for(const [id,actor]of Object.entries(overrides))overrides[id]={...ACTORS[id],...actor,attributes:attributesByActor[id]||[]};
  cibaActorCache.set(key,overrides);return overrides;
}
